const buffer = await this.helpers.getBinaryDataBuffer($itemIndex,'data');
if (buffer.length > 10 * 1024 * 1024) throw new Error('The downloaded brief exceeds the 10 MB input limit.');
// $binary is metadata-only. Preserve the actual input item and its binary bytes/ID.
return $input.item;

let file = {};
let delivery = {};
try { file = $('Workflow Configuration').item.json; } catch {}
try { delivery = $('Prepare Report Delivery').item.json; } catch {}
const candidate = String(file.errorNotificationEmail || '');
const canNotify = /^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+$/.test(candidate) && !/PLACEHOLDER|[<>]/i.test(candidate);
const subjectName = String(file.name || 'unknown file').replace(/[\r\n]/g,' ');
const emailMessage = [
 'Client brief processing did not complete.','File: '+String(file.name || 'unknown file'),
 'Execution ID: '+String($execution.id || 'manual'),'',
 'Completion was not verified for this failed path.',
 'Open this execution in n8n to inspect the failed node. Raw brief text and API error bodies are not included in this email.',
 ...(delivery.documentUrl ? ['','A partial report may already exist: '+delivery.documentUrl] : []),'',
 'Check credentials, configuration, file format and extraction, model availability, research access, and Google permissions.',
 'Scanned PDFs need OCR first. Protected or malformed DOCX files are not supported.',
 'Check Gmail Sent before retrying: an email request can time out after delivery. If a document or log row already exists, reconcile it before retrying to avoid duplicate artifacts.'
].join('\n');
return {json:{canNotify,sendTo:candidate,emailSubject:'Client brief analysis failed: '+subjectName,emailMessage}};

const expected = $('Prepare Report Delivery').item.json;
const normalize = text => String(text).replace(/\r\n/g,'\n').trim();
if ($json.documentId !== expected.documentId || typeof $json.content !== 'string' || normalize($json.content) !== normalize(expected.reportContent)) throw new Error('The Google Doc contents do not match the generated report. Do not send a completion email.');
return {json:expected};

const documentId = $json.id;
if (typeof documentId !== 'string' || !/^[A-Za-z0-9_-]+$/.test(documentId)) throw new Error('Google Docs create did not return a valid id.');
const report = $('Generate Comprehensive Report').item.json;
const documentUrl = 'https://docs.google.com/document/d/'+documentId+'/edit';
const safeFileName = String(report.originalFileName).replace(/[\r\n]/g,' ');
const emailSubject = 'Client brief analysis ready: '+safeFileName;
const emailMessage = [
 'Your client brief analysis is ready.','',
 'File: '+report.originalFileName,'Client: '+report.briefAnalysis.clientName,
 'Industry: '+report.briefAnalysis.industry,'Project type: '+report.briefAnalysis.projectType,'',
 'Summary:',report.briefAnalysis.summary,'','Full report: '+documentUrl,'',
 'AI-generated draft. Review the findings and sources before sharing or acting on them.'
].join('\n');
return {json:{...report,documentId,documentUrl,emailSubject,emailMessage}};

let value = $json.output ?? $json.text ?? $json;
if (typeof value === 'string') value = JSON.parse(value.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,''));
if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('AI output is not a JSON object.');
for (const key of ["budgetBenchmarks","timelineEstimates","limitations"]) { if (typeof value[key] !== 'string' || value[key].length > (key === 'summary' ? 4000 : 2000)) throw new Error('Invalid AI string field: '+key); }
for (const key of ["industryTrends","competitorInsights","marketOpportunities","bestPractices","technologicalFactors","regulatoryConsiderations"]) { if (!Array.isArray(value[key]) || value[key].length > 15 || value[key].some(item=>typeof item !== 'string' || item.length > 2000)) throw new Error('Invalid AI list field: '+key); }
if (!Array.isArray(value.sources) || value.sources.length > 10) throw new Error('Invalid research sources.');
for (const source of value.sources) { if (!source || typeof source.title !== 'string' || source.title.length > 300 || typeof source.url !== 'string' || source.url.length > 2000 || !/^https?:\/\/[^\s]+$/i.test(source.url)) throw new Error('Invalid research source URL.'); }
return {json:{...$('Normalize Brief Analysis').item.json,industryResearch:value}};

let value = $json.output ?? $json.text ?? $json;
if (typeof value === 'string') value = JSON.parse(value.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,''));
if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('AI output is not a JSON object.');
for (const key of ["summary","clientName","industry","projectType","targetAudience","budget","timeline"]) { if (typeof value[key] !== 'string' || value[key].length > (key === 'summary' ? 4000 : 2000)) throw new Error('Invalid AI string field: '+key); }
for (const key of ["clientNeeds","clientGoals","challenges","risks","recommendations","keyQuestions"]) { if (!Array.isArray(value[key]) || value[key].length > 15 || value[key].some(item=>typeof item !== 'string' || item.length > 2000)) throw new Error('Invalid AI list field: '+key); }
return {json:{briefAnalysis:value}};

if ($json.extractionError) throw new Error($json.extractionError);
if (typeof $json.text !== 'string') throw new Error('Text extraction returned no text field.');
const text = $json.text.replace(/^\uFEFF/,'').replace(/\u0000/g,'').trim();
if (text.length < 50) throw new Error('The brief contains fewer than 50 readable characters. Scanned or image-only files require OCR first.');
if (text.length > 50000) throw new Error('The brief exceeds 50,000 characters. Split it into smaller documents rather than silently truncating it.');
return {json:{text}};

const item = $input.item;
const binary = item.binary || {};
if (!binary.data) throw new Error('DOCX download did not provide binary data.');
// Preserve raw binary data/ID; $binary omits inline data bytes.
// DOCX is a ZIP archive. Change metadata only, not the actual file bytes.
return {json: item.json, binary: {...binary, data: {...binary.data, fileExtension:'zip', mimeType:'application/zip', fileName:String(binary.data.fileName || 'brief.docx') + '.zip'}}};

const j = $json;
for (const key of ['clientSummariesFolderId', 'trackingSheetId', 'accountManagerEmail', 'errorNotificationEmail']) {
  if (typeof j[key] !== 'string' || !j[key].trim() || /PLACEHOLDER|[<>]/i.test(j[key])) throw new Error('Configure ' + key + ' before activating this workflow.');
}
for (const key of ['clientSummariesFolderId', 'trackingSheetId']) {
  if (!/^[A-Za-z0-9_-]+$/.test(j[key].trim())) throw new Error(key + ' must contain a Google ID, not a URL.');
}
for (const key of ['accountManagerEmail', 'errorNotificationEmail']) {
  if (!/^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+$/.test(j[key].trim())) throw new Error(key + ' must contain one valid email address.');
}
if (!j.id || !j.name) throw new Error('Google Drive event is missing its file ID or name.');
const mime = String(j.mimeType || '').toLowerCase();
const extension = String(j.name).split('.').pop().toLowerCase();
const mimeKinds = {'application/pdf':'pdf', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document':'docx', 'text/plain':'txt'};
let fileKind = mimeKinds[mime];
if (!fileKind && (!mime || mime === 'application/octet-stream')) fileKind = ['pdf','docx','txt'].includes(extension) ? extension : undefined;
if (!fileKind) throw new Error('Unsupported format. Upload a text-based PDF, standard DOCX, or UTF-8 TXT file.');
if (j.size !== undefined && Number(j.size) > 10 * 1024 * 1024) throw new Error('The client brief exceeds the 10 MB input limit.');
return {json: {...j, fileKind}};

const {briefAnalysis:analysis,industryResearch:research} = $json;
if (!analysis || !research) throw new Error('Both validated analysis and research are required.');
const file = $('Workflow Configuration').item.json;
const date = new Date().toISOString();
const lines = ['CLIENT BRIEF ANALYSIS','File: '+file.name,'Analysis date (UTC): '+date,'','AI-generated draft. Verify factual claims and cited sources before making decisions.',''];
const scalar = (title,value) => { if (value && value.trim()) lines.push(title.toUpperCase(),value,''); };
const list = (title,values) => { lines.push(title.toUpperCase()); lines.push(...(values.length ? values.map((v,i)=>(i+1)+'. '+v) : ['Not specified.']),''); };
scalar('Executive summary',analysis.summary);
lines.push('CLIENT INFORMATION','Client: '+analysis.clientName,'Industry: '+analysis.industry,'Project type: '+analysis.projectType,'');
scalar('Target audience',analysis.targetAudience);
scalar('Budget information from the brief',analysis.budget);
scalar('Budget benchmarks from research',research.budgetBenchmarks);
scalar('Timeline from the brief',analysis.timeline);
scalar('Timeline estimates from research',research.timelineEstimates);
list('Client needs',analysis.clientNeeds);
list('Client goals',analysis.clientGoals);
list('Challenges',analysis.challenges);
list('Risks',analysis.risks);
list('Industry trends',research.industryTrends);
list('Competitor insights',research.competitorInsights);
list('Market opportunities',research.marketOpportunities);
list('Best practices',research.bestPractices);
list('Technological factors',research.technologicalFactors);
list('Regulatory considerations (not legal advice)',research.regulatoryConsiderations);
list('Strategic recommendations',analysis.recommendations);
list('Questions for client clarification',analysis.keyQuestions);
lines.push('RESEARCH SOURCES',...(research.sources.length ? research.sources.map(s=>s.title+': '+s.url) : ['No sources returned. Treat research as unverified.']),'');
scalar('Research limitations',research.limitations);
const reportContent = lines.join('\n')+'\n';
if (reportContent.length > 100000) throw new Error('Generated report exceeds the 100,000-character output limit.');
return {json:{
 ...$json,reportContent,originalFileName:file.name,sourceFileId:file.id,analysisDate:date,
 stats:{needsCount:analysis.clientNeeds.length,goalsCount:analysis.clientGoals.length,challengesCount:analysis.challenges.length,risksCount:analysis.risks.length,recommendationsCount:analysis.recommendations.length,questionsCount:analysis.keyQuestions.length,trendsCount:research.industryTrends.length}
}};

