const items = $input.all();
const results = [];
const decode = value => value.replace(/&(#x[0-9a-f]+|#[0-9]+|amp|lt|gt|quot|apos);/gi, (match, entity) => {
  const entities = {amp:'&',lt:'<',gt:'>',quot:'"',apos:"'"};
  if (entities[entity.toLowerCase()] !== undefined) return entities[entity.toLowerCase()];
  const point = entity.toLowerCase().startsWith('#x') ? parseInt(entity.slice(2),16) : parseInt(entity.slice(1),10);
  return Number.isInteger(point) && point > 0 && point <= 0x10FFFF && !(point >= 0xD800 && point <= 0xDFFF) ? String.fromCodePoint(point) : '';
});
for (let index=0; index<items.length; index++) {
  try {
    const item = items[index];
    const candidates = Object.entries(item.binary || {}).filter(([key,value]) => {
      const path = [value.directory,value.fileName].filter(Boolean).join('/').replace(/\\/g,'/').replace(/^\.\//,'');
      return path === 'word/document.xml' || value.fileName === 'word/document.xml';
    });
    if (candidates.length !== 1) throw new Error('DOCX must contain exactly one word/document.xml part.');
    const buffer = await this.helpers.getBinaryDataBuffer(index,candidates[0][0]);
    if (buffer.length > 4 * 1024 * 1024) throw new Error('DOCX document XML exceeds the 4 MB limit.');
    const xml = buffer.toString('utf8');
    if (/<!DOCTYPE|<!ENTITY/i.test(xml)) throw new Error('DOCX XML entity declarations are not supported.');
    const match = xml.match(/xmlns:([A-Za-z_][\w.-]*)=["']http:\/\/(?:schemas\.openxmlformats\.org\/wordprocessingml\/2006\/main|purl\.oclc\.org\/ooxml\/wordprocessingml\/main)["']/);
    if (!match) throw new Error('The DOCX WordprocessingML namespace was not found.');
    const prefix = match[1].replace(/[.*+?^$(){}|[\]\\]/g,'\\$&');
    const tokens = new RegExp('<'+prefix+':t(?:\\s[^>]*)?>([\\s\\S]*?)<\\/'+prefix+':t>|<'+prefix+':(tab|br|cr)\\b[^>]*\\/?>|<\\/'+prefix+':p\\s*>','g');
    let text = '';
    for (const token of xml.matchAll(tokens)) {
      if (token[1] !== undefined) text += decode(token[1]);
      else if (token[2] === 'tab') text += '\t';
      else text += '\n';
    }
    results.push({json:{...item.json,text},pairedItem:{item:index}});
  } catch (error) {
    results.push({json:{...items[index].json,extractionError:error.message,text:''},pairedItem:{item:index}});
  }
}
return results;
